      arabicText: "هُوَ الَّذِي أَنزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ مُّحْكَمَاتٌ هُنَّ أُمُّ الْكِتَابِ وَأُخَرُ مُتَشَابِهَاتٌ ۖ فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ابْتِغَاءَ الْفِتْنَةِ وَابْتِغَاءَ تَأْوِيلِهِ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُ إِلَّا اللَّهُ ۗ وَالرَّاسِخُونَ فِي الْعِلْمِ يَقُولُونَ آمَنَّا بِهِ كُلٌّ مِّنْ عِندِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّا أُولُو الْأَلْبَابِ",
      urduTranslation: "وہی ہے جس نے آپ پر کتاب نازل فرمائی، جس میں سے کچھ آیات محکم (واضح و پختہ) ہیں، وہی کتاب کی اصل بنیاد ہیں اور دوسری متشابہ (کثیر مفہوم والی) ہیں۔ پس جن کے دلوں میں کجی ہے وہ فتنے کی تلاش اور من پسند تاویل کی غرض سے متشابہات کے پیچھے پڑتے ہیں، حالانکہ ان کی حقیقی تاویل اللہ کے سوا کوئی نہیں جانتا۔ اور جو علم میں پختہ کار ہیں وہ کہتے ہیں: ہم اس پر ایمان لائے، یہ سب ہمارے رب ہی کی طرف سے ہے۔ اور عقل والے ہی نصیحت قبول کرتے ہیں",
      englishTranslation: "It is He who has sent down to you, [O Muhammad], the Book; in it are verses [that are] precise - they are the foundation of the Book - and others unspecific. As for those in whose hearts is deviation [from truth], they will follow that of it which is unspecific, seeking discord and seeking an interpretation [suitable to them]. And no one knows its [true] interpretation except Allah. But those firm in knowledge say, \"We believe in it. All [of it] is from our Lord.\" And no one will be reminded except those of understanding.",
